spec.expr:
sum by (node) (
  rate(
    container_network_receive_bytes_total{
      job="cadvisor",
      id="/"
    }[5m]
  )
)

sum by (node) (
  rate(
    container_network_transmit_bytes_total{
      job="cadvisor",
      id="/"
    }[5m]
  )
)

(
  100 *
  sum(
    rate(
      http_server_request_duration_count{
        job=~"opentelemetry-demo/.*",
        http_response_status_code=~"5.."
      }[5m]
    )
  )
  /
  sum(
    rate(
      http_server_request_duration_count{
        job=~"opentelemetry-demo/.*"
      }[5m]
    )
  )
)
or vector(0)

sum by (node) (
  rate(
    container_cpu_usage_seconds_total{
      job="cadvisor",
      id="/"
    }[5m]
  )
)
